try:
    print('>>> f = hasattr')
    print('>>> x = type(1)')
    print('>>> y = 1j')
    print('>>> f(x, y)')
    f = hasattr
    x = type(1)
    y = 1j
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
